import Foundation
import Cocoa

func sendClick(at point: NSPoint) {
    let mouse = CGEvent(mouseEventSource: nil, mouseType: .leftMouseDown, mouseCursorPosition: point, timestamp: 0)
    mouse?.post(tap: .cghidEventTap)

    let mouseUp = CGEvent(mouseEventSource: nil, mouseType: .leftMouseUp, mouseCursorPosition: point, timestamp: 0)
    mouseUp?.post(tap: .cghidEventTap)
}

// Click the Open button at approximately these coordinates
sendClick(at: NSPoint(x: 486, y: 863))
print("Click sent to (486, 863)")
EOF
